from abc import abstractmethod
from typing import Protocol

from dishka import Provider, Scope, WithParents, make_container, provide_all


def test_provide_all_with_parents_protocol_in_request_scope():
    """The example from the issue resolves both the implementation and protocol."""
    class MyProtocol(Protocol):
        @abstractmethod
        def __call__(self, data: bytes) -> bytes: ...

    class MyImpl(MyProtocol):
        def __call__(self, data: bytes) -> bytes:
            return data

    class MyProvider(Provider):
        scope = Scope.REQUEST
        interactors = provide_all(WithParents[MyImpl])

    container = make_container(MyProvider())
    try:
        with container() as request_container:
            impl = request_container.get(MyImpl)
            protocol = request_container.get(MyProtocol)

            assert isinstance(impl, MyImpl)
            assert protocol is impl
            assert protocol(b"data") == b"data"
    finally:
        container.close()


def test_provide_all_with_parents_preserves_parent_aliases():
    """WithParents must provide parents from the same factory, not new factories."""
    class A1:
        pass

    class A2(A1):
        pass

    class A3(A2):
        pass

    class MyProvider(Provider):
        scope = Scope.APP
        provides = provide_all(WithParents[A3])

    container = make_container(MyProvider())
    try:
        instance = container.get(A3)

        assert isinstance(instance, A3)
        assert container.get(A2) is instance
        assert container.get(A1) is instance
    finally:
        container.close()


def test_provide_all_on_instance_supports_with_parents_and_regular_classes():
    class Base:
        pass

    class Child(Base):
        pass

    class RegularClass:
        pass

    provider = Provider(scope=Scope.APP)
    provider.provide_all(WithParents[Child], RegularClass)

    container = make_container(provider)
    try:
        child = container.get(Child)

        assert container.get(Base) is child
        assert isinstance(container.get(RegularClass), RegularClass)
    finally:
        container.close()


def test_provide_all_supports_multiple_with_parents_arguments():
    class FirstBase:
        pass

    class FirstChild(FirstBase):
        pass

    class SecondBase:
        pass

    class SecondChild(SecondBase):
