import pytest

from ucumvert import (
    PintUcumRegistry,
    UcumToPintStrTransformer,
    ucum_preprocessor,
)
from ucumvert.parser import get_ucum_parser


@pytest.fixture(scope="module")
def ureg():
    return PintUcumRegistry()


def assert_prefixed_iu_per_liter(ureg, actual, expected_units, scale_to_iu):
    """Check both the requested Pint representation and its meaning."""
    # A numerically scaled quantity such as 0.001 international_unit / liter
    # is not the requested conversion to a prefixed Pint unit.
    assert actual.magnitude == pytest.approx(1.0)
    assert str(actual.units) == expected_units
    assert actual == ureg(expected_units)
    assert actual.to("international_unit / liter").magnitude == pytest.approx(
        scale_to_iu
    )


@pytest.mark.parametrize(
    ("ucum_code", "expected_units", "scale_to_iu"),
    [
        ("m[IU]/L", "milliinternational_unit / liter", 1e-3),
        ("k[IU]/L", "kilointernational_unit / liter", 1e3),
        # Prefix handling must be general, not special-cased to milli and kilo.
        ("u[IU]/L", "microinternational_unit / liter", 1e-6),
        ("da[IU]/L", "decainternational_unit / liter", 1e1),
    ],
)
def test_prefixed_international_unit_per_liter(
    ureg, ucum_code, expected_units, scale_to_iu
):
    actual = ureg.from_ucum(ucum_code)

    assert_prefixed_iu_per_liter(ureg, actual, expected_units, scale_to_iu)
    assert "meter" not in str(actual.units)


@pytest.mark.parametrize(
    ("ucum_code", "expected_units", "scale_to_iu"),
    [
        ("m[IU]/L", "milliinternational_unit / liter", 1e-3),
        ("k[IU]/L", "kilointernational_unit / liter", 1e3),
        ("u[IU]/L", "microinternational_unit / liter", 1e-6),
    ],
)
def test_string_transformer_handles_prefixed_international_unit(
    ureg, ucum_code, expected_units, scale_to_iu
):
    parsed = get_ucum_parser().parse(ucum_code)
    pint_expression = UcumToPintStrTransformer().transform(parsed)

    # The generated expression must itself be valid Pint input. In particular,
    # it must not contain invalid text such as "milli[IU]".
    actual = ureg(pint_expression)

    assert_prefixed_iu_per_liter(ureg, actual, expected_units, scale_to_iu)


def test_preprocessor_handles_prefixed_international_unit(ureg):
    ureg.preprocessors.append(ucum_preprocessor)
    try:
        actual = ureg("m[IU]/L")
    finally:
        ureg.preprocessors.remove(ucum_preprocessor)

    assert_prefixed_iu_per_liter(
        ureg, actual, "milliinternational_unit / liter", 1e-3
    )


def test_unprefixed_international_unit_is_unchanged(ureg):
    actual = ureg.from_ucum("[IU]/L")

    assert actual.magnitude == pytest.approx(1.0)
    assert str(actual.units) == "international_unit / liter"
    assert actual == ureg("international_unit / liter")


@pytest.mark.parametrize(
    ("ucum_code", "pint_code"),
    [
        ("m", "meter"),
        ("kg", "kilogram"),
        ("mL", "milliliter"),
        ("m/s", "meter / second"),
    ],
)
def test_ordinary_metric_units_and_prefixes_are_unchanged(
    ureg, ucum_code, pint_code
):
    assert ureg.from_ucum(ucum_code) == ureg(pint_code)

