from dishka import Provider, Scope, WithParents, make_container, provide_all


class MyProtocol(Protocol):
    @abstractmethod
    def __call__(self, data: bytes) -> bytes: ...


class MyImpl(MyProtocol):
    def __call__(self, data: bytes) -> bytes:
        return data


def test_provide_all_with_parents_and_protocol() -> None:
    """The example from the issue resolves the implementation and its protocol."""
    class MyProvider(Provider):
        scope = Scope.REQUEST

        interactors = provide_all(WithParents[MyImpl])

    container = make_container(MyProvider())
    with container() as request_container:
        implementation = request_container.get(MyImpl)

        assert type(implementation) is MyImpl
        assert implementation(b"data") == b"data"
        assert request_container.get(MyImpl) is implementation
        assert request_container.get(MyProtocol) is implementation


def test_provide_all_with_parents_preserves_single_factory_and_aliases() -> None:
    """Every parent must resolve to the object made by the child's factory."""
    class Dependency:
        pass

    class Base:
        pass

    class Intermediate(Base):
        pass

    class Implementation(Intermediate):
        def __init__(self, dependency: Dependency) -> None:
            self.dependency = dependency

    class RegularClass:
        pass

    class MyProvider(Provider):
        scope = Scope.APP

        dependencies = provide_all(
            WithParents[Implementation],
            Dependency,
            RegularClass,
        )

    container = make_container(MyProvider())
    implementation = container.get(Implementation)

    assert isinstance(implementation.dependency, Dependency)
    assert implementation.dependency is container.get(Dependency)
    assert container.get(Intermediate) is implementation
    assert container.get(Base) is implementation
    assert isinstance(container.get(RegularClass), RegularClass)


