from typing import Protocol

from dishka import Provider, Scope, WithParents, make_container, provide_all


class MyProtocol(Protocol):
    @abstractmethod
    def __call__(self, data: bytes) -> bytes: ...


class MyImpl(MyProtocol):
    def __call__(self, data: bytes) -> bytes:
        return data


def test_provide_all_with_parents_matches_issue_example() -> None:
    class MyProvider(Provider):
        scope = Scope.REQUEST

        interactors = provide_all(WithParents[MyImpl])

    with closing(make_container(MyProvider())) as app_container:
        with app_container() as request_container:
            impl = request_container.get(MyImpl)
            protocol = request_container.get(MyProtocol)

            assert isinstance(impl, MyImpl)
            assert impl(b"data") == b"data"
            # Parents must be aliases of the implementation, not new factories.
            assert protocol is impl
            assert request_container.get(MyImpl) is impl

        # The provider's REQUEST scope must still apply to the new factory.
        with app_container() as another_request:
            assert another_request.get(MyImpl) is not impl


class MultiBase:
    pass


class LeftProtocol(Protocol):
    @abstractmethod
    def left(self) -> str: ...


class RightProtocol(Protocol):
    @abstractmethod
    def right(self) -> int: ...


class MultiImpl(MultiBase, LeftProtocol, RightProtocol):
    def left(self) -> str:
        return "left"

    def right(self) -> int:
        return 42


class OtherProtocol(Protocol):
    @abstractmethod
    def value(self) -> str: ...


class OtherImpl(OtherProtocol):
    def value(self) -> str:
        return "other"


def test_provide_all_supports_multiple_with_parents_and_all_parents() -> None:
    class MultiProvider(Provider):
        scope = Scope.APP

        services = provide_all(
            WithParents[MultiImpl],
            WithParents[OtherImpl],
        )

    with closing(make_container(MultiProvider())) as container:
        multi = container.get(MultiImpl)

        assert container.get(MultiBase) is multi
        assert container.get(LeftProtocol) is multi
        assert container.get(RightProtocol) is multi
        assert multi.left() == "left"
        assert multi.right() == 42

        other = container.get(OtherImpl)
        assert isinstance(other, OtherImpl)
        assert container.get(OtherProtocol) is other
        assert other.value() == "other"


class Dependency:
    pass


class WorkerProtocol(Protocol):
    @abstractmethod
    def run(self) -> Dependency: ...


class Worker(WorkerProtocol):
    def __init__(self, dependency: Dependency) -> None:
        self.dependency = dependency

    def run(self) -> Dependency:
        return self.dependency


class PlainService:
    pass


def test_with_parents_can_be_mixed_with_regular_provide_all_entries() -> None:
    class MixedProvider(Provider):
        scope = Scope.APP

        services = provide_all(
            WithParents[Worker],
            Dependency,
            PlainService,
        )

    with closing(make_container(MixedProvider())) as container:
        worker = container.get(Worker)
        dependency = container.get(Dependency)

        assert isinstance(worker, Worker)
        assert worker.dependency is dependency
        assert worker.run() is dependency
        assert container.get(WorkerProtocol) is worker

        # Existing provide_all behavior for ordinary classes must be preserved.
        plain = container.get(PlainService)
        assert isinstance(plain, PlainService)
        assert container.get(PlainService) is plain


