import pytest

from ucumvert import (
    PintUcumRegistry,
    UcumToPintStrTransformer,
    UcumToPintTransformer,
    ucum_preprocessor,
)
from ucumvert.parser import get_ucum_parser


PREFIXED_IU_CASES = [
    ("m[IU]/L", "milliinternational_unit / liter", 1e-3),
    ("k[IU]/L", "kilointernational_unit / liter", 1e3),
    ("u[IU]/L", "microinternational_unit / liter", 1e-6),
    ("M[IU]/L", "megainternational_unit / liter", 1e6),
]


@pytest.fixture(scope="module")
def ureg():
    return PintUcumRegistry()


@pytest.fixture(scope="module")
def parser():
    return get_ucum_parser()


def assert_prefixed_iu_conversion(quantity, expected_units, scale_in_iu):
    """Check both the requested Pint representation and its UCUM meaning."""
    # A result such as 0.001 international_unit/liter is convertible to the
    # expected value, but is not the prefixed Pint unit requested in the issue.
    assert quantity.magnitude == pytest.approx(1.0)
    assert str(quantity.units) == expected_units

    converted = quantity.to("international_unit / liter")
    assert converted.magnitude == pytest.approx(scale_in_iu)


@pytest.mark.parametrize("use_registry", [True, False], ids=["registry", "transformer"])
@pytest.mark.parametrize(
    ("ucum_code", "expected_units", "scale_in_iu"), PREFIXED_IU_CASES
)
def test_prefixed_international_unit_to_pint(
    ureg, parser, use_registry, ucum_code, expected_units, scale_in_iu
):
    if use_registry:
        quantity = ureg.from_ucum(ucum_code)
    else:
        parsed = parser.parse(ucum_code)
        quantity = UcumToPintTransformer(ureg=ureg).transform(parsed)

    assert_prefixed_iu_conversion(quantity, expected_units, scale_in_iu)


@pytest.mark.parametrize(
    ("ucum_code", "expected_units", "scale_in_iu"), PREFIXED_IU_CASES
)
def test_prefixed_international_unit_to_pint_string(
    ureg, parser, ucum_code, expected_units, scale_in_iu
):
    parsed = parser.parse(ucum_code)
    pint_expression = UcumToPintStrTransformer().transform(parsed)

    quantity = ureg(pint_expression)
    assert_prefixed_iu_conversion(quantity, expected_units, scale_in_iu)


@pytest.mark.parametrize(
    ("ucum_code", "expected_units", "scale_in_iu"), PREFIXED_IU_CASES[:2]
)
def test_prefixed_international_unit_through_preprocessor(
    ureg, ucum_code, expected_units, scale_in_iu
):
    pint_expression = ucum_preprocessor(ucum_code)
    quantity = ureg(pint_expression)

    assert_prefixed_iu_conversion(quantity, expected_units, scale_in_iu)


def test_prefixed_international_unit_with_exponent(ureg):
    quantity = ureg.from_ucum("m[IU]2/L")
    expected = ureg("milliinternational_unit ** 2 / liter")

    assert quantity.magnitude == pytest.approx(1.0)
    assert str(quantity.units) == str(expected.units)
    assert quantity.to("international_unit ** 2 / liter").magnitude == pytest.approx(
        1e-6
    )


@pytest.mark.parametrize(
    ("ucum_code", "expected_units"),
    [
        ("[IU]/L", "international_unit / liter"),
        ("m/L", "meter / liter"),
        # With an explicit multiplication operator, "m" must remain meter;
        # only the adjacent prefix in m[IU] denotes milli.
        ("m.[IU]/L", "meter * international_unit / liter"),
    ],
)
def test_related_unprefixed_and_meter_expressions_are_unchanged(
    ureg, ucum_code, expected_units
):
    quantity = ureg.from_ucum(ucum_code)
    expected = ureg(expected_units)

    assert quantity.magnitude == pytest.approx(1.0)
    assert str(quantity.units) == str(expected.units)

from abc import abstractmethod
from typing import Protocol

from dishka import Provider, Scope, WithParents, make_container, provide_all


class IssueProtocol(Protocol):
    @abstractmethod
    def __call__(self, data: bytes) -> bytes: ...


class IssueImpl(IssueProtocol):
    def __call__(self, data: bytes) -> bytes:
        return data


class BaseService:
    pass


class IntermediateService(BaseService):
    pass


class ConcreteService(IntermediateService):
    pass


class LeftProtocol(Protocol):
    def left(self) -> str: ...


class RightProtocol(Protocol):
    def right(self) -> str: ...


class BothProtocols(LeftProtocol, RightProtocol):
    def left(self) -> str:
        return "left"

    def right(self) -> str:
        return "right"


class Standalone:
    pass


class Plain:
    pass


class Gateway:
    pass


class HandlerProtocol(Protocol):
    def handle(self) -> str: ...


class Handler(HandlerProtocol):
    def __init__(self, gateway: Gateway) -> None:
        self.gateway = gateway

    def handle(self) -> str:
        return "handled"


def test_provide_all_with_parents_in_provider_class() -> None:
    class MyProvider(Provider):
        scope = Scope.REQUEST

        interactors = provide_all(WithParents[IssueImpl])

    container = make_container(MyProvider())
    try:
        with container() as request_container:
            impl = request_container.get(IssueImpl)

            assert isinstance(impl, IssueImpl)
            assert impl(b"data") == b"data"
            assert request_container.get(IssueProtocol) is impl
            assert request_container.get(IssueImpl) is impl

        # The provider-level scope must also apply to the WithParents factory.
        with container() as another_request_container:
            assert another_request_container.get(IssueImpl) is not impl
    finally:
        container.close()


def test_provide_all_with_parents_supports_multiple_and_deep_hierarchies() -> None:
    class MyProvider(Provider):
        scope = Scope.APP

        services = provide_all(
            WithParents[ConcreteService],
            WithParents[BothProtocols],
            WithParents[Standalone],  # WithParents with no additional parents
            Plain,  # Ordinary provide_all entries must continue to work
        )

    container = make_container(MyProvider())
    try:
        concrete = container.get(ConcreteService)
        assert container.get(IntermediateService) is concrete
        assert container.get(BaseService) is concrete

        both = container.get(BothProtocols)
        assert container.get(LeftProtocol) is both
        assert container.get(RightProtocol) is both
        assert both.left() == "left"
        assert both.right() == "right"

        assert isinstance(container.get(Standalone), Standalone)
        assert isinstance(container.get(Plain), Plain)
    finally:
        container.close()


def test_instance_provide_all_with_parents_uses_concrete_constructor() -> None:
    provider = Provider(scope=Scope.APP)
    provider.provide(Gateway)
    provider.provide_all(WithParents[Handler])

    container = make_container(provider)
    try:
        handler = container.get(Handler)

        assert isinstance(handler, Handler)
        assert handler.handle() == "handled"
        assert handler.gateway is container.get(Gateway)
        assert container.get(HandlerProtocol) is handler
    finally:
        container.close()

from abc import abstractmethod
from typing import Generic, Protocol, TypeVar

from dishka import Provider, Scope, WithParents, make_container, provide_all


T = TypeVar("T")


def test_provide_all_with_parents_issue_example() -> None:
    class MyProtocol(Protocol):
        @abstractmethod
        def __call__(self, data: bytes) -> bytes: ...

    class MyImpl(MyProtocol):
        def __call__(self, data: bytes) -> bytes:
            return data

    class MyProvider(Provider):
        scope = Scope.REQUEST

        interactors = provide_all(WithParents[MyImpl])

    container = make_container(MyProvider())
    with container() as request_container:
        impl = request_container.get(MyImpl)
        protocol = request_container.get(MyProtocol)

        assert type(impl) is MyImpl
        assert protocol is impl
        assert protocol(b"request") == b"request"


def test_provide_all_with_parents_multiple_and_mixed_entries() -> None:
    class Base:
        pass

    class Derived(Base):
        pass

    class Left(Protocol):
        @abstractmethod
        def left(self) -> str: ...

    class Right(Protocol):
        @abstractmethod
        def right(self) -> str: ...

    class MultiImpl(Left, Right):
        def left(self) -> str:
            return "left"

        def right(self) -> str:
            return "right"

    class Standalone:
        pass

    class Ordinary:
        pass

    class MyProvider(Provider):
        scope = Scope.APP

        entries = provide_all(
            WithParents[Derived],
            WithParents[MultiImpl],
            WithParents[Standalone],
            Ordinary,
        )

    container = make_container(MyProvider())

    derived = container.get(Derived)
    assert type(derived) is Derived
    assert container.get(Base) is derived

    multi = container.get(MultiImpl)
    assert type(multi) is MultiImpl
    assert container.get(Left) is multi
    assert container.get(Right) is multi
    assert multi.left() == "left"
    assert multi.right() == "right"

    assert type(container.get(Standalone)) is Standalone
    assert type(container.get(Ordinary)) is Ordinary


def test_provide_all_on_instance_with_parents_and_dependencies() -> None:
    class Dependency:
        pass

    class ServiceProtocol(Protocol):
        @abstractmethod
        def get_dependency(self) -> Dependency: ...

    class Service(ServiceProtocol):
        def __init__(self, dependency: Dependency) -> None:
            self.dependency = dependency

        def get_dependency(self) -> Dependency:
            return self.dependency

    provider = Provider(scope=Scope.APP)
    provider.provide_all(Dependency, WithParents[Service])

    container = make_container(provider)
    dependency = container.get(Dependency)
    service = container.get(Service)

    assert type(service) is Service
    assert container.get(ServiceProtocol) is service
    assert service.get_dependency() is dependency


def test_provide_all_with_parents_generic_alias() -> None:
    class GenericBase(Generic[T]):
