    class GenericImpl(GenericBase[T], Generic[T]):
        pass

    provider = Provider(scope=Scope.APP)
    provider.provide_all(WithParents[GenericImpl[int]])

    container = make_container(provider)
    impl = container.get(GenericImpl[int])

    assert type(impl) is GenericImpl
    assert container.get(GenericBase[int]) is impl

