"""Tests for Store.list filtering of live and soft-deleted items."""

import pytest

from borgstore.constants import DEL_SUFFIX
from borgstore.store import ItemInfo, Store


LEVELS_CONFIG = {"flat/": [0], "nested/": [1]}


@pytest.fixture()
def store(tmp_path):
    store = Store(url=tmp_path.as_uri(), levels=LEVELS_CONFIG)
    store.create()
    try:
        with store:
            yield store
    finally:
        store.destroy()


def expected_infos(items):
    return [
        ItemInfo(name=name, exists=True, size=len(value), directory=False)
        for name, value in sorted(items.items())
    ]


def listed_infos(store, namespace, deleted):
    infos = list(store.list(namespace, deleted=deleted))
    return sorted(infos, key=lambda info: info.name)


@pytest.mark.parametrize("namespace", ["flat", "nested"])
def test_list_deleted_selects_only_requested_item_kind(store, namespace):
    """deleted=False and deleted=True must return disjoint, filtered sets."""
    live_items = {
        "00000000": b"live",
        "22222222": b"also live",
    }
    soft_deleted_items = {
        "11111111": b"soft deleted",
        "33333333": b"",
    }

    for name, value in {**live_items, **soft_deleted_items}.items():
        store.store(f"{namespace}/{name}", value)
    for name in soft_deleted_items:
        store.move(f"{namespace}/{name}", delete=True)

    # Omitting the argument must retain the default of listing only live items.
    default_infos = sorted(store.list(namespace), key=lambda info: info.name)
    assert default_infos == expected_infos(live_items)
    assert listed_infos(store, namespace, deleted=False) == expected_infos(live_items)

    deleted_infos = listed_infos(store, namespace, deleted=True)
    assert deleted_infos == expected_infos(soft_deleted_items)
    # Soft-deleted items are presented under their original, usable names.
    assert all(not info.name.endswith(DEL_SUFFIX) for info in deleted_infos)


def test_list_deleted_true_is_empty_when_nothing_is_soft_deleted(store):
    namespace = "flat"
    store.store("flat/aaaaaaaa", b"a")
    store.store("flat/bbbbbbbb", b"b")

    assert [info.name for info in store.list(namespace)] == ["aaaaaaaa", "bbbbbbbb"]
    assert list(store.list(namespace, deleted=True)) == []


def test_list_filters_follow_soft_delete_and_undelete_transitions(store):
    namespace = "flat"
    names = ["aaaaaaaa", "bbbbbbbb"]
    for name in names:
        store.store(f"{namespace}/{name}", name.encode())

    for name in names:
        store.move(f"{namespace}/{name}", delete=True)

    assert list(store.list(namespace, deleted=False)) == []
    assert [info.name for info in store.list(namespace, deleted=True)] == names

    store.move(f"{namespace}/aaaaaaaa", undelete=True)
    assert [info.name for info in store.list(namespace, deleted=False)] == ["aaaaaaaa"]
    assert [info.name for info in store.list(namespace, deleted=True)] == ["bbbbbbbb"]

    store.move(f"{namespace}/bbbbbbbb", undelete=True)
    assert [info.name for info in store.list(namespace, deleted=False)] == names
    assert list(store.list(namespace, deleted=True)) == []

