def test_mutable_headers_in_place_merge_with_dict():
    headers = MutableHeaders()
    original_instance = headers

    headers |= {"X-Header": "string"}

    assert headers is original_instance
    assert dict(headers) == {"x-header": "string"}
    assert headers.raw == [(b"x-header", b"string")]
    assert repr(headers) == "MutableHeaders({'x-header': 'string'})"


def test_mutable_headers_in_place_merge_updates_case_insensitively():
    headers = MutableHeaders(
        raw=[
            (b"x-token", b"old"),
            (b"x-other", b"unchanged"),
            (b"x-token", b"duplicate"),
        ]
    )

    headers |= {"X-TOKEN": "new", "X-Added": "value"}

    # Updating a header replaces all of its duplicate entries while retaining
    # the position of the first entry and normalizing names to lowercase.
    assert headers.raw == [
        (b"x-token", b"new"),
        (b"x-other", b"unchanged"),
        (b"x-added", b"value"),
    ]
    assert headers.getlist("X-Token") == ["new"]


def test_mutable_headers_merge_returns_new_independent_instance():
    original = MutableHeaders({"X-Existing": "original"})

    merged = original | {"X-New": "new"}

    assert isinstance(merged, MutableHeaders)
    assert merged is not original
    assert dict(original) == {"x-existing": "original"}
    assert dict(merged) == {"x-existing": "original", "x-new": "new"}

    # Mutating either result must not affect the other instance.
    merged["X-Existing"] = "changed"
    original["X-Original-Only"] = "value"
    assert original["x-existing"] == "original"
    assert "x-original-only" not in merged


