    original = MutableHeaders(
        raw=[(b"x-header", b"first"), (b"x-header", b"second")]
    )

    merged = original | {"X-HEADER": "merged"}

    assert original.raw == [(b"x-header", b"first"), (b"x-header", b"second")]
    assert merged.raw == [(b"x-header", b"merged")]
    assert merged.getlist("x-header") == ["merged"]


