import numpy
import pandas
import pytest
from sklearn.linear_model import LinearRegression

from skore import CrossValidationReporter
from skore.item.cross_validation_aggregation_item import CrossValidationAggregationItem


@pytest.fixture
def regression_data():
    rng = numpy.random.RandomState(42)
    X = rng.normal(size=(30, 2))
    y = 3 * X[:, 0] - 2 * X[:, 1] + rng.normal(scale=0.1, size=30)
    return X, y


def _put_reporters(project, regression_data, scorings):
    X, y = regression_data
    for scoring in scorings:
        reporter = CrossValidationReporter(
            LinearRegression(), X, y, cv=3, scoring=scoring
        )
        project.put("cv", reporter)

    items = project.get_item_versions("cv")
    assert len(items) == len(scorings)
    return items


def _as_float_array(values):
    # Missing metrics may be represented by NaN, None, or pandas.NA.
    return numpy.asarray(
        [
            numpy.nan if value is None or pandas.isna(value) else value
            for value in values
        ],
        dtype=float,
    )


def _assert_metric_traces(figure, items, metric_names, n_splits=3):
    traces = {trace.name: trace for trace in figure.data}
    assert set(metric_names).issubset(traces)

    # Exploding preserves the original run index for every fold in that run.
    # Consequently, run_number must not become a sequential fold number.
    expected_run_numbers = numpy.repeat(numpy.arange(len(items)), n_splits)

    for metric_name in metric_names:
        expected_values = []
        for item in items:
            serialized = item.cv_results_serialized
            if metric_name in serialized:
                values = serialized[metric_name]
                assert len(values) == n_splits
                expected_values.extend(values)
            else:
                # A metric absent from a run must remain aligned with that run's folds.
                expected_values.extend([numpy.nan] * n_splits)

        trace = traces[metric_name]
        numpy.testing.assert_array_equal(trace.x, expected_run_numbers)
        numpy.testing.assert_allclose(
            _as_float_array(trace.y),
            numpy.asarray(expected_values, dtype=float),
            equal_nan=True,
        )


@pytest.mark.parametrize(
    "scoring",
    [
        pytest.param(
            ["neg_mean_absolute_error", "r2", "explained_variance"],
            id="multiple-extra-scores",
        ),
        pytest.param(("r2",), id="single-score-tuple"),
    ],
)
def test_cross_validation_accepts_extra_scores(
    in_memory_project, regression_data, scoring
):
    """Extra scores must work when aggregating with an older default-scoring run."""
    # The default run has test_score, whereas the second run has test_<metric>
    # columns. This is the mixed-column situation from the reported failure.
    _put_reporters(in_memory_project, regression_data, [None, scoring])


@pytest.mark.parametrize(
    "scoring, metric_names",
    [
        pytest.param(
            ["neg_mean_absolute_error", "r2", "explained_variance"],
            (
                "test_neg_mean_absolute_error",
                "test_r2",
                "test_explained_variance",
            ),
            id="multiple-extra-scores",
        ),
        pytest.param(("r2",), ("test_r2",), id="single-score-tuple"),
    ],
)
def test_aggregation_with_extra_scores_preserves_all_results(
    in_memory_project, regression_data, scoring, metric_names
):
    items = _put_reporters(in_memory_project, regression_data, [scoring, scoring])

    aggregation = CrossValidationAggregationItem.factory(items)

    _assert_metric_traces(aggregation.plot, items, metric_names)


@pytest.mark.parametrize(
    "scorings, metric_names",
    [
        pytest.param(
            ("r2", ["r2", "explained_variance"]),
            ("test_score", "test_r2", "test_explained_variance"),
            id="single-then-multiple",
        ),
        pytest.param(
            (["r2", "explained_variance"], "r2"),
            ("test_score", "test_r2", "test_explained_variance"),
            id="multiple-then-single",
        ),
        pytest.param(
            ("r2", ["neg_mean_absolute_error", "explained_variance"]),
            (
                "test_score",
                "test_neg_mean_absolute_error",
                "test_explained_variance",
            ),
            id="disjoint-metric-sets",
        ),
    ],
)
def test_aggregation_aligns_metrics_from_different_scoring_configurations(
    in_memory_project, regression_data, scorings, metric_names
):
    items = _put_reporters(in_memory_project, regression_data, scorings)

    aggregation = CrossValidationAggregationItem.factory(items)

    _assert_metric_traces(aggregation.plot, items, metric_names)

