import importlib

from setuptools_scm import Configuration
from setuptools_scm import _entrypoints
from setuptools_scm.version import format_version, meta


VERSION_SCHEME = "ttg_uninstalled_schemes.schemes.version_scheme"
LOCAL_SCHEME = "ttg_uninstalled_schemes.schemes.local_scheme"
NONE_SCHEME = "ttg_uninstalled_schemes.schemes.none_scheme"
FALLBACK_SCHEME = "ttg_uninstalled_schemes.schemes.fallback_scheme"


def _make_version(version_scheme, local_scheme="no-local-version"):
    config = Configuration(
        version_scheme=version_scheme,
        local_scheme=local_scheme,
    )
    return meta(
        tag="1.2.3",
        distance=4,
        node="abc123",
        dirty=False,
        config=config,
    )


def _format(version, version_scheme, local_scheme="no-local-version"):
    return format_version(
        version,
        version_scheme=version_scheme,
        local_scheme=local_scheme,
    )


def _install_source_only_scheme_module(tmp_path, monkeypatch):
    """Make schemes importable without installing any distribution/entry point."""
    package = tmp_path / "ttg_uninstalled_schemes"
    package.mkdir()
    (package / "__init__.py").write_text("")
    (package / "schemes.py").write_text(
        """
def version_scheme(version):
    return f"{version.tag}.post{version.distance}"


def local_scheme(version):
    return f"+{version.node}"


def none_scheme(version):
    return None


def fallback_scheme(version):
    return f"2.0.0.dev{version.distance}"
"""
    )
    monkeypatch.syspath_prepend(str(tmp_path))
    importlib.invalidate_caches()


def test_version_scheme_accepts_qualified_name_without_entry_point(
    tmp_path, monkeypatch
):
    _install_source_only_scheme_module(tmp_path, monkeypatch)

    # Simulate installation time: the project's entry point is not registered,
    # even though its source tree is importable.
    real_iter_entry_points = _entrypoints.iter_entry_points

    def iter_without_project_entry_point(group, name=None):
        if group == "setuptools_scm.version_scheme" and name == VERSION_SCHEME:
            return iter(())
        return real_iter_entry_points(group, name)

    monkeypatch.setattr(
        _entrypoints, "iter_entry_points", iter_without_project_entry_point
    )

    version = _make_version(VERSION_SCHEME)
    assert _format(version, VERSION_SCHEME) == "1.2.3.post4"


def test_local_scheme_also_accepts_qualified_name(tmp_path, monkeypatch):
    _install_source_only_scheme_module(tmp_path, monkeypatch)

    def main_scheme(version):
        return str(version.tag)

    version = _make_version(main_scheme, local_scheme=LOCAL_SCHEME)
    assert _format(version, main_scheme, LOCAL_SCHEME) == "1.2.3+abc123"


def test_qualified_names_work_inside_scheme_lists(tmp_path, monkeypatch):
    _install_source_only_scheme_module(tmp_path, monkeypatch)

    schemes = [NONE_SCHEME, FALLBACK_SCHEME]
    version = _make_version(schemes)

    # A scheme returning None must still fall through to the next scheme.
    assert _format(version, schemes) == "2.0.0.dev4"


def test_existing_entry_point_scheme_names_remain_supported():
    version = _make_version("guess-next-dev")
    assert _format(version, "guess-next-dev") == "1.2.4.dev4"


def test_dotted_entry_point_name_still_works_when_import_fails(monkeypatch):
    dotted_name = "ttg.dotted-entrypoint"

    class FakeEntryPoint:
        name = dotted_name

        @staticmethod
        def load():
            return lambda version: "3.4.5"

    real_iter_entry_points = _entrypoints.iter_entry_points

    def fake_iter_entry_points(group, name=None):
        if group == "setuptools_scm.version_scheme" and name == dotted_name:
            return iter((FakeEntryPoint(),))
        return real_iter_entry_points(group, name)

    monkeypatch.setattr(_entrypoints, "iter_entry_points", fake_iter_entry_points)

    version = _make_version(dotted_name)
    assert _format(version, dotted_name) == "3.4.5"

"""Regression tests for the default UTF-8 encoding passed to lxml."""

import pytest

from parsel import Selector
from parsel import selector as selector_module


TITLE = "Café — Parsel"
HTML = f"<html><head><title>{TITLE}</title></head><body><p>content</p></body></html>"


@pytest.fixture
def lxml_without_utf8_alias(monkeypatch):
    """Simulate lxml builds which accept ``utf-8`` but reject ``utf8``.

    Some lxml builds accept both spellings, so merely parsing a document would
    not reliably reproduce the Windows/conda failure on every test platform.
    """

    def make_strict_parser(parser_cls):
        class ParserWithoutUtf8Alias(parser_cls):
            def __init__(self, *args, **kwargs):
                if kwargs.get("encoding") == "utf8":
                    raise LookupError("unknown encoding: 'b'utf8''")
                super().__init__(*args, **kwargs)

        return ParserWithoutUtf8Alias

    for selector_type in ("html", "xml"):
        parser_group = selector_module._ctgroup[selector_type]
        monkeypatch.setitem(
            parser_group,
            "_parser",
            make_strict_parser(parser_group["_parser"]),
        )


@pytest.mark.parametrize("input_kind", ["text", "body"])
@pytest.mark.parametrize("huge_tree", [True, False])
def test_default_encoding_supports_css_title_selection(
    lxml_without_utf8_alias, input_kind, huge_tree
):
    """The tutorial's response.css("title") scenario works for text and bytes."""
    kwargs = {input_kind: HTML if input_kind == "text" else HTML.encode("utf-8")}
    response = Selector(huge_tree=huge_tree, **kwargs)

    assert len(response.css("title")) == 1
    assert response.css("title::text").get() == TITLE


def test_default_encoding_is_also_used_for_lazy_text_selection(
    lxml_without_utf8_alias,
):
    """Text selectors build their HTML root only when XPath/CSS is first used."""
    response = Selector(text=HTML, type="text")

    assert response.css("title::text").get() == TITLE


def test_default_encoding_works_for_xml(lxml_without_utf8_alias):
    response = Selector(
        text=f"<root><title>{TITLE}</title></root>",
        type="xml",
    )

    assert response.css("title::text").get() == TITLE


def test_default_encoding_works_for_empty_documents(lxml_without_utf8_alias):
    response = Selector(text="")

    assert response.css("title").getall() == []


def test_explicit_non_utf_encoding_is_not_overridden(lxml_without_utf8_alias):
    """Fixing the default must not force every document to be decoded as UTF-8."""
    body = "<html><head><title>café</title></head></html>".encode("cp1252")

    response = Selector(body=body, encoding="cp1252")

    assert response.css("title::text").get() == "café"


def test_default_bytes_input_still_auto_detects_json(lxml_without_utf8_alias):
    """Changing the default encoding must preserve JSON bytes auto-detection."""
    response = Selector(body='{"title": "Café", "items": ["a", "b"]}'.encode("utf-8"))

    assert response.type == "json"
    assert response.jmespath("title").get() == "Café"
    assert response.jmespath("items").getall() == ["a", "b"]

import importlib
import sys

import pytest

from setuptools_scm import Configuration
from setuptools_scm import _entrypoints
from setuptools_scm.version import format_version
from setuptools_scm.version import meta


_PACKAGE_NAME = "setuptools_scm_uninstalled_scheme_project"
_MODULE_NAME = f"{_PACKAGE_NAME}.versioning"


@pytest.fixture
def qualified_scheme_module(tmp_path, monkeypatch):
    """Provide schemes in importable project sources, without installing a dist."""
    package = tmp_path / _PACKAGE_NAME
    package.mkdir()
    (package / "__init__.py").write_text("", encoding="utf-8")
    (package / "versioning.py").write_text(
        """
def custom_version_scheme(version):
    return "qualified-{0}-{1}".format(version.tag, version.distance or 0)


def other_version_scheme(version):
    return "fallback-{0}".format(version.tag)


def no_version(version):
    return None


def custom_local_scheme(version):
    dirty = ".dirty" if version.dirty else ""
    return "+{0}{1}".format(version.node, dirty)
""",
        encoding="utf-8",
    )

    # This models the chicken-and-egg situation: the project's sources are
    # importable, but its distribution and entry points are not installed.
    monkeypatch.syspath_prepend(str(tmp_path))
    for name in (_MODULE_NAME, _PACKAGE_NAME):
        sys.modules.pop(name, None)
    importlib.invalidate_caches()

    yield _MODULE_NAME

    for name in (_MODULE_NAME, _PACKAGE_NAME):
        sys.modules.pop(name, None)


def render_version(
    version_scheme,
    *,
    local_scheme="no-local-version",
    tag="1.2.3",
    distance=2,
    node="gabcdef",
    dirty=False,
):
    config = Configuration(
        version_scheme=version_scheme,
        local_scheme=local_scheme,
    )
    scm_version = meta(
        tag=tag,
        distance=distance,
        node=node,
        dirty=dirty,
        config=config,
    )
    return format_version(
        scm_version,
        version_scheme=version_scheme,
        local_scheme=local_scheme,
    )


@pytest.mark.parametrize("distance", [0, 4])
def test_version_scheme_accepts_a_qualified_name(
    qualified_scheme_module, distance
):
    qualified_name = f"{qualified_scheme_module}.custom_version_scheme"

    result = render_version(qualified_name, distance=distance)

    assert result == f"qualified-1.2.3-{distance}"


def test_local_scheme_also_accepts_a_qualified_name(qualified_scheme_module):
    version_scheme = f"{qualified_scheme_module}.custom_version_scheme"
    local_scheme = f"{qualified_scheme_module}.custom_local_scheme"

    result = render_version(
        version_scheme,
        local_scheme=local_scheme,
        dirty=True,
    )

    assert result == "qualified-1.2.3-2+gabcdef.dirty"


def test_qualified_names_work_in_scheme_lists_and_can_return_none(
    qualified_scheme_module,
):
    schemes = [
        f"{qualified_scheme_module}.no_version",
        f"{qualified_scheme_module}.other_version_scheme",
    ]

    assert render_version(schemes) == "fallback-1.2.3"


def test_qualified_names_can_be_mixed_with_entry_point_names(
    qualified_scheme_module,
):
    schemes = (
        "an-entry-point-that-is-not-installed",
        f"{qualified_scheme_module}.other_version_scheme",
    )

    assert render_version(schemes) == "fallback-1.2.3"


def test_existing_entry_point_names_still_work():
    assert render_version("guess-next-dev") == "1.2.4.dev2"


def test_dotted_entry_point_names_remain_supported(monkeypatch):
    """A dot in an existing entry-point name must not make it unusable."""
    scheme_name = "project.custom-scheme"

    class EntryPoint:
        name = scheme_name

        @staticmethod
        def load():
            return lambda version: "loaded-from-entry-point"

    original_iter_entry_points = _entrypoints.iter_entry_points

    def iter_entry_points(group, name=None):
        if group == "setuptools_scm.version_scheme" and name == scheme_name:
            return iter([EntryPoint()])
        return original_iter_entry_points(group, name)

    monkeypatch.setattr(_entrypoints, "iter_entry_points", iter_entry_points)

    assert render_version(scheme_name) == "loaded-from-entry-point"


def test_direct_callables_remain_supported():
    def custom_scheme(version):
        return f"callable-{version.tag}"

    assert render_version(custom_scheme) == "callable-1.2.3"

import pytest

from add_trailing_comma import _fix_src


def fix(src):
    return _fix_src(src, py35_plus=False)


def test_multiline_string_concatenation_is_fixed_in_one_pass():
    src = "f('long'\n  'literal')"
    intermediate = "f(\n    'long'\n    'literal'\n)"
    expected = "f(\n    'long'\n    'literal',\n)"

    # The first pass must produce the fully fixed result, not merely unhug the
    # call and require another pass to add the comma.
    assert fix(src) == expected
    assert fix(intermediate) == expected
    assert fix(expected) == expected


@pytest.mark.parametrize('prefix', ['obj.method', 'funcs[0]', 'factory()'])
def test_multiline_string_concatenation_in_other_call_expressions(prefix):
    src = prefix + "('long'\n  'literal')"
    expected = prefix + "(\n    'long'\n    'literal',\n)"

    # Attribute access, subscription, and a returned callable are all calls,
    # just like the simple NAME(...) call in the issue.
    assert fix(src) == expected


@pytest.mark.parametrize(
    ('src', 'expected'),
    [
        (
            "f(b'long'\n  b'literal')",
            "f(\n    b'long'\n    b'literal',\n)",
        ),
        (
            "f('one'\n  'two'\n  'three')",
            "f(\n    'one'\n    'two'\n    'three',\n)",
        ),
        (
            "f(value='long'\n  'literal')",
            "f(\n    value='long'\n    'literal',\n)",
        ),
    ],
)
def test_other_multiline_implicit_literal_concatenations(src, expected):
    assert fix(src) == expected


@pytest.mark.parametrize(
    ('src', 'expected'),
    [
        (
            "value = ('long'\n  'literal')",
            "value = (\n    'long'\n    'literal'\n)",
        ),
        (
            "for char in ('long'\n  'literal'):\n    pass",
            "for char in (\n    'long'\n    'literal'\n):\n    pass",
        ),
        (
            "value = True and ('long'\n  'literal')",
            "value = True and (\n    'long'\n    'literal'\n)",
        ),
    ],
)
def test_parenthesized_concatenation_does_not_become_a_tuple(src, expected):
    # A trailing comma is only safe for a call. In these contexts it would
    # change the concatenated string into a one-element tuple.
    assert fix(src) == expected


def test_sole_generator_argument_does_not_get_a_trailing_comma():
    src = "f('long'\n  'literal' for _ in items)"
    expected = "f(\n    'long'\n    'literal' for _ in items\n)"

    # A comma after an unparenthesized sole generator argument is invalid.
    assert fix(src) == expected


def test_single_triple_quoted_string_is_left_alone():
    src = "f('''long\nliteral''')"

    # This is one string token, not adjacent literals concatenated over lines.
    assert fix(src) == src

import pytest

from parsel import Selector
from parsel import selector as selector_module
from parsel.selector import create_root_node


HTML = "<html><head><title>Café 東京</title></head><body></body></html>"
XML = "<root><title>Café 東京</title></root>"


@pytest.fixture
def lxml_requiring_canonical_utf8(monkeypatch):
    """Simulate lxml builds that reject the non-canonical ``utf8`` alias."""

    def make_strict_parser(parser_cls):
        def strict_parser(*args, **kwargs):
            encoding = kwargs.get("encoding")
            if isinstance(encoding, str) and encoding.lower() in {
                "utf8",
                "utf_8",
            }:
                raise LookupError("unknown encoding: 'b'utf8''")
            return parser_cls(*args, **kwargs)

        return strict_parser

    for selector_type in ("html", "xml"):
        group = selector_module._ctgroup[selector_type]
        monkeypatch.setitem(
            group, "_parser", make_strict_parser(group["_parser"])
        )


@pytest.mark.parametrize(
    "selector_kwargs",
    [
        {"text": HTML},
        {"body": HTML.encode("utf-8")},
        {"text": XML, "type": "xml"},
    ],
    ids=["html-text", "html-bytes", "xml-text"],
)
def test_default_encoding_css_selection(
    selector_kwargs, lxml_requiring_canonical_utf8
):
    selector = Selector(**selector_kwargs)

    assert selector.css("title::text").get() == "Café 東京"


def test_text_selector_css_uses_canonical_default_encoding(
    lxml_requiring_canonical_utf8,
):
    selector = Selector(text="<p>Hello</p>", type="text")

    assert selector.css("p::text").get() == "Hello"


def test_create_root_node_uses_canonical_default_encoding(
    lxml_requiring_canonical_utf8,
):
    root = create_root_node(
        HTML,
        parser_cls=selector_module._ctgroup["html"]["_parser"],
    )

    assert root.xpath("string(//title)") == "Café 東京"


@pytest.mark.parametrize(
    "selector_kwargs",
    [{}, {"encoding": "utf-8"}],
    ids=["default-encoding", "explicit-canonical-encoding"],
)
def test_utf8_json_bytes_are_still_autodetected(selector_kwargs):
    selector = Selector(
        body=b'{"title": "Example", "answer": 42}',
        **selector_kwargs,
    )

    assert selector.type == "json"
    assert selector.jmespath("title").get() == "Example"
    assert selector.jmespath("answer").get() == 42


def test_explicit_non_utf8_encoding_is_still_honored():
    body = "<html><head><title>Café</title></head></html>".encode("cp1252")

    selector = Selector(body=body, encoding="cp1252")

    assert selector.css("title::text").get() == "Café"

import inspect
from unittest.mock import Mock

import pytest

import gspread.utils as utils
from gspread.utils import (
    DateTimeOption,
    Dimension,
    ValueInputOption,
    ValueRenderOption,
)
from gspread.worksheet import ValueRange, Worksheet


SPREADSHEET_ID = "spreadsheet-id"
SHEET_TITLE = "Sheet 1"


def values_response(values, range_name="'Sheet 1'!A1:B2"):
    return {
        "range": range_name,
        "majorDimension": "ROWS",
        "values": values,
    }


@pytest.fixture
def client():
    return Mock()


@pytest.fixture
def worksheet(client):
    properties = {
        "sheetId": 123,
        "title": SHEET_TITLE,
        "index": 0,
        "gridProperties": {"rowCount": 100, "columnCount": 26},
    }
    return Worksheet(SPREADSHEET_ID, client, properties)


def test_kwargs_helpers_are_removed():
    assert not hasattr(utils, "accepted_kwargs")
    assert not hasattr(utils, "filter_dict_values")


def test_former_decorator_kwargs_are_explicit_public_parameters():
    expected_parameters = {
        # combine_merged_cells must remain the second argument: it was already
        # a positional parameter before accepted_kwargs was removed.
        "get_values": [
            "range_name",
            "combine_merged_cells",
            "major_dimension",
            "value_render_option",
            "date_time_render_option",
        ],
        "get_all_values": [
            "major_dimension",
            "value_render_option",
            "date_time_render_option",
        ],
        "row_values": [
            "row",
            "major_dimension",
            "value_render_option",
            "date_time_render_option",
        ],
        "get": [
            "range_name",
            "major_dimension",
            "value_render_option",
            "date_time_render_option",
        ],
        "batch_get": [
            "ranges",
            "major_dimension",
            "value_render_option",
            "date_time_render_option",
        ],
        "update": [
            "range_name",
            "values",
            "raw",
            "major_dimension",
            "value_input_option",
            "include_values_in_response",
            "response_value_render_option",
            "response_date_time_render_option",
        ],
        "batch_update": [
            "data",
            "raw",
            "value_input_option",
            "include_values_in_response",
            "response_value_render_option",
            "response_date_time_render_option",
        ],
    }

    for method_name, expected in expected_parameters.items():
        parameters = list(
            inspect.signature(getattr(Worksheet, method_name)).parameters.values()
        )
        assert parameters[0].name == "self"
        parameters = parameters[1:]
        assert [parameter.name for parameter in parameters] == expected
        assert all(
            parameter.kind is not inspect.Parameter.VAR_KEYWORD
            for parameter in parameters
        )

    assert inspect.signature(Worksheet.get_values).parameters[
        "combine_merged_cells"
    ].default is False
    assert inspect.signature(Worksheet.update).parameters["values"].default is None
    assert inspect.signature(Worksheet.update).parameters["raw"].default is True
    assert inspect.signature(Worksheet.batch_update).parameters["raw"].default is True


def test_get_values_preserves_positional_combine_merged_cells_argument(
    worksheet, client
):
    """The second positional argument was combine_merged_cells before the change."""
    client.values_get.return_value = values_response(
        [["top left", None], [None, None]]
    )
    client.fetch_sheet_metadata.return_value = {
        "sheets": [
            {
                "properties": {"title": SHEET_TITLE, "sheetId": 123},
                "merges": [
                    {
                        "startRowIndex": 0,
                        "endRowIndex": 2,
                        "startColumnIndex": 0,
                        "endColumnIndex": 2,
                    }
                ],
            }
        ]
    }

    result = worksheet.get_values("A1:B2", True)

    assert result == [["top left", "top left"], ["top left", "top left"]]
    client.values_get.assert_called_once_with(
        SPREADSHEET_ID,
        "'Sheet 1'!A1:B2",
        params={
            "majorDimension": None,
            "valueRenderOption": None,
            "dateTimeRenderOption": None,
        },
    )
    client.fetch_sheet_metadata.assert_called_once_with(SPREADSHEET_ID)


def test_get_passes_none_options_without_filtering_them(worksheet, client):
    client.values_get.return_value = values_response([], "'Sheet 1'")

    result = worksheet.get()

    assert isinstance(result, ValueRange)
    assert result == []
    client.values_get.assert_called_once_with(
        SPREADSHEET_ID,
        "'Sheet 1'",
        params={
            "majorDimension": None,
            "valueRenderOption": None,
            "dateTimeRenderOption": None,
        },
    )


def test_get_all_values_forwards_all_render_options(worksheet, client):
    client.values_get.return_value = values_response([["1", "2"]], "'Sheet 1'")

    result = worksheet.get_all_values(
        major_dimension=Dimension.cols,
        value_render_option=ValueRenderOption.unformatted,
        date_time_render_option=DateTimeOption.serial_number,
    )

    assert result == [["1", "2"]]
    client.values_get.assert_called_once_with(
        SPREADSHEET_ID,
        "'Sheet 1'",
