"""Regression tests for the platform-dependent ``utf8`` parser failure.

Some lxml builds, including the Windows build from the issue, reject the
``utf8`` alias when it is passed to a parser. The fixture below reproduces
that strictness so these tests exercise the failure on every platform.
"""

import pytest

from parsel import Selector
from parsel import selector as selector_module


HTML = "<html><head><title>Café</title></head><body><p>Hello</p></body></html>"
XML = "<root><title>Café</title><p>Hello</p></root>"


def _reject_utf8_alias(parser_cls):
    """Wrap an lxml parser factory to emulate the affected lxml builds."""

    def strict_parser(*args, **kwargs):
        if kwargs.get("encoding") == "utf8":
            raise LookupError("unknown encoding: b'utf8'")
        return parser_cls(*args, **kwargs)

    return strict_parser


@pytest.fixture
def lxml_requiring_canonical_utf8(monkeypatch):
    for input_type in ("html", "xml"):
        parser_cls = selector_module._ctgroup[input_type]["_parser"]
        monkeypatch.setitem(
            selector_module._ctgroup[input_type],
            "_parser",
            _reject_utf8_alias(parser_cls),
        )


@pytest.mark.parametrize("use_bytes", [False, True], ids=["text", "bytes"])
def test_default_html_css_selection_uses_portable_utf8(
    lxml_requiring_canonical_utf8, use_bytes
):
    kwargs = {"body": HTML.encode("utf-8")} if use_bytes else {"text": HTML}

    response = Selector(**kwargs)

    assert response.type == "html"
    assert len(response.css("title")) == 1
    assert response.css("title::text").get() == "Café"


@pytest.mark.parametrize("use_bytes", [False, True], ids=["text", "bytes"])
def test_default_xml_selection_uses_portable_utf8(
    lxml_requiring_canonical_utf8, use_bytes
):
    kwargs = {"body": XML.encode("utf-8")} if use_bytes else {"text": XML}

    selector = Selector(type="xml", **kwargs)

    assert selector.type == "xml"
    assert selector.css("title::text").get() == "Café"


def test_text_selector_reparsing_uses_portable_default_encoding(
    lxml_requiring_canonical_utf8,
):
    # CSS/XPath on a text selector reparses its text through Selector._get_root,
    # which must use the same portable default as normal selector construction.
    selector = Selector(text="<p>Café</p>", type="text")

    assert selector.css("p::text").get() == "Café"


@pytest.mark.parametrize("encoding", [None, "utf-8"], ids=["default", "explicit"])
def test_utf8_json_bytes_are_autodetected(encoding):
    body = '{"name": "Café", "items": ["first", "second"]}'.encode("utf-8")
    kwargs = {} if encoding is None else {"encoding": encoding}

    selector = Selector(body=body, **kwargs)

    assert selector.type == "json"
    assert selector.jmespath("name").get() == "Café"
    assert selector.jmespath("items").getall() == ["first", "second"]


@pytest.mark.parametrize("use_bytes", [False, True], ids=["text", "bytes"])
def test_explicit_non_utf8_encoding_is_still_honored(use_bytes):
    # Use the canonical IANA name: some lxml builds also reject shorter aliases
    # such as "latin-1", independently of the UTF-8 default being tested here.
    encoding = "iso-8859-1"
    kwargs = (
        {"body": HTML.encode(encoding)} if use_bytes else {"text": HTML}
    )

    selector = Selector(encoding=encoding, **kwargs)

    assert selector.css("title::text").get() == "Café"

import jwt
import pytest

from jwt.exceptions import InvalidAudienceError, MissingRequiredClaimError


KEY = "test-secret"
ALGORITHMS = ["HS256"]


def decode_payload(payload, **kwargs):
    token = jwt.encode(payload, KEY, algorithm="HS256")
    return jwt.decode(token, KEY, algorithms=ALGORITHMS, **kwargs)


def test_null_aud_is_accepted_when_no_audience_is_expected():
    payload = {"sub": "1234567890", "aud": None, "name": "example"}

    decoded = decode_payload(payload)

    # Ignoring aud for validation must not remove it from the decoded payload.
    assert decoded == payload


@pytest.mark.parametrize("audience", ["expected", ["expected"], []])
def test_null_aud_is_treated_as_missing_when_an_audience_is_expected(audience):
    # Just like an omitted aud claim, null cannot satisfy a requested audience.
    with pytest.raises(MissingRequiredClaimError) as exc_info:
        decode_payload({"aud": None}, audience=audience)

    assert exc_info.value.claim == "aud"


@pytest.mark.parametrize("payload", [{}, {"aud": None}])
def test_null_aud_does_not_satisfy_a_required_aud_claim(payload):
    with pytest.raises(MissingRequiredClaimError) as exc_info:
        decode_payload(payload, options={"require": ["aud"]})

    assert exc_info.value.claim == "aud"


@pytest.mark.parametrize("aud", ["", [], 0, False, {}, "unexpected"])
def test_only_null_aud_is_ignored(aud):
    # Other values, including other falsy values, retain the existing behavior.
    with pytest.raises(InvalidAudienceError):
        decode_payload({"aud": aud})


@pytest.mark.parametrize(
    ("token_aud", "audience"),
    [
        ("expected", "expected"),
        (["other", "expected"], "expected"),
        ("expected", ["other", "expected"]),
    ],
)
def test_non_null_audience_validation_still_accepts_matches(token_aud, audience):
    assert decode_payload({"aud": token_aud}, audience=audience) == {
        "aud": token_aud
    }


def test_non_null_audience_validation_still_rejects_mismatches():
    with pytest.raises(InvalidAudienceError):
        decode_payload({"aud": "other"}, audience="expected")

