"""Regression tests for treating a JSON null ``aud`` claim as unspecified."""

import pytest

from jwt.api_jwt import PyJWT
from jwt.exceptions import InvalidAudienceError, MissingRequiredClaimError


SECRET = "secret"
ALGORITHMS = ["HS256"]


@pytest.fixture
def jwt_api():
    return PyJWT()


def encode_and_decode(jwt_api, payload, **kwargs):
    token = jwt_api.encode(payload, SECRET)
    return jwt_api.decode(token, SECRET, algorithms=ALGORITHMS, **kwargs)


def test_null_aud_is_ignored_when_no_audience_is_expected(jwt_api):
    """A token containing {"aud": null} must decode without an audience."""
    payload = {"some": "payload", "aud": None}

    decoded = encode_and_decode(jwt_api, payload)

    # Ignoring the claim for validation must not discard it from the result.
    assert decoded == payload


@pytest.mark.parametrize(
    "payload",
    [
        {"some": "payload"},
        {"some": "payload", "aud": None},
    ],
    ids=["aud-unspecified", "aud-null"],
)
def test_null_aud_behaves_like_missing_aud_when_audience_is_expected(
    jwt_api, payload
):
    """A null aud cannot satisfy an audience required by the application."""
    with pytest.raises(MissingRequiredClaimError) as exc_info:
        encode_and_decode(jwt_api, payload, audience="urn:me")

    assert exc_info.value.claim == "aud"


@pytest.mark.parametrize(
    "payload",
    [
        {"some": "payload"},
        {"some": "payload", "aud": None},
    ],
    ids=["aud-unspecified", "aud-null"],
)
def test_null_aud_does_not_satisfy_explicitly_required_claim(jwt_api, payload):
    """Treating null as unspecified also applies to options['require']."""
    with pytest.raises(MissingRequiredClaimError) as exc_info:
        encode_and_decode(jwt_api, payload, options={"require": ["aud"]})

    assert exc_info.value.claim == "aud"


@pytest.mark.parametrize("aud", ["", [], 0, False, {}, [None]])
def test_only_null_aud_is_treated_as_unspecified(jwt_api, aud):
    """Other present, non-null aud values retain the existing validation."""
    payload = {"some": "payload", "aud": aud}

    with pytest.raises(InvalidAudienceError):
        encode_and_decode(jwt_api, payload)

import pytest

import jwt
from jwt.exceptions import InvalidAudienceError, MissingRequiredClaimError


KEY = "secret"
ALGORITHMS = ["HS256"]


def decode_payload(payload, **kwargs):
    token = jwt.encode(payload, KEY, algorithm="HS256")
    return jwt.decode(token, KEY, algorithms=ALGORITHMS, **kwargs)


def test_null_aud_is_ignored_when_no_audience_is_expected():
    payload = {"sub": "subject", "aud": None}

    # Validation should succeed without removing the claim from the result.
    assert decode_payload(payload) == payload


@pytest.mark.parametrize(
    "payload",
    [{}, {"aud": None}],
    ids=["aud-unspecified", "aud-null"],
)
def test_null_aud_is_treated_as_unspecified_when_audience_is_expected(payload):
    with pytest.raises(MissingRequiredClaimError) as exc_info:
        decode_payload(payload, audience="expected-audience")

    assert exc_info.value.claim == "aud"


@pytest.mark.parametrize(
    "payload",
    [{}, {"aud": None}],
    ids=["aud-unspecified", "aud-null"],
)
def test_null_aud_does_not_satisfy_an_explicitly_required_claim(payload):
    with pytest.raises(MissingRequiredClaimError) as exc_info:
        decode_payload(payload, options={"require": ["aud"]})

    assert exc_info.value.claim == "aud"


@pytest.mark.parametrize("aud", ["", [], {}, 0, False])
def test_other_falsey_aud_values_are_not_treated_as_unspecified(aud):
    with pytest.raises(InvalidAudienceError):
        decode_payload({"aud": aud})


@pytest.mark.parametrize(
    "payload",
    [
        {"aud": "expected-audience"},
        {"aud": ["another-audience", "expected-audience"]},
    ],
)
def test_valid_non_null_audience_validation_is_unchanged(payload):
    assert decode_payload(payload, audience="expected-audience") == payload


def test_non_null_audience_mismatch_still_fails():
    with pytest.raises(InvalidAudienceError):
        decode_payload({"aud": "another-audience"}, audience="expected-audience")

