    return Worksheet(SPREADSHEET_ID, client, properties), client


def api_response(values=None, range_name="'Sheet1'!A1"):
    return {
        "range": range_name,
        "majorDimension": Dimension.rows,
        "values": [] if values is None else values,
    }


def effective_params(mock_method):
    """None-valued query parameters have no effect on the HTTP request."""
    _, kwargs = mock_method.call_args
    params = kwargs.get("params") or {}
    return {key: value for key, value in params.items() if value is not None}


