)
def test_formerly_decorated_methods_have_explicit_signatures(
    method_name, expected_parameters
):
    signature = inspect.signature(getattr(Worksheet, method_name))

    assert list(signature.parameters) == ["self"] + [
        name for name, _ in expected_parameters
    ]
    assert not any(
        parameter.kind is inspect.Parameter.VAR_KEYWORD
        for parameter in signature.parameters.values()
    )

    for name, default in expected_parameters:
        parameter = signature.parameters[name]
        assert parameter.default == default
        assert parameter.kind in (
            inspect.Parameter.POSITIONAL_OR_KEYWORD,
            inspect.Parameter.KEYWORD_ONLY,
        )


