import inspect
from copy import deepcopy

import pytest

import gspread.utils as utils
from gspread.utils import (
    DateTimeOption,
    Dimension,
    ValueInputOption,
    ValueRenderOption,
)
from gspread.worksheet import ValueRange, Worksheet


SPREADSHEET_ID = "spreadsheet-id"


def read_params(
    major_dimension=None,
    value_render_option=None,
    date_time_render_option=None,
):
    """Unset options must retain the old behavior and not be sent to the API."""
    params = {
        "majorDimension": major_dimension,
        "valueRenderOption": value_render_option,
        "dateTimeRenderOption": date_time_render_option,
    }
    return {key: value for key, value in params.items() if value is not None}


class RecordingClient:
    """Offline stand-in for the worksheet's HTTP client."""

    def __init__(self):
        self.values = [["a", "b"], ["c"]]
        self.values_get_calls = []
        self.values_batch_get_calls = []
        self.values_update_calls = []
        self.values_batch_update_calls = []
        self.metadata = {"sheets": []}

    def _value_range_response(self, range_name, params):
        params = params or {}
        return {
            "range": range_name,
            "majorDimension": params.get("majorDimension") or Dimension.rows,
            "values": deepcopy(self.values),
        }

    def values_get(self, spreadsheet_id, range_name, params=None):
        self.values_get_calls.append(
            {
                "spreadsheet_id": spreadsheet_id,
                "range_name": range_name,
                "params": params,
            }
        )
        return self._value_range_response(range_name, params)

    def values_batch_get(self, spreadsheet_id, ranges=None, params=None):
        self.values_batch_get_calls.append(
            {
                "spreadsheet_id": spreadsheet_id,
                "ranges": ranges,
                "params": params,
            }
        )
        return {
            "valueRanges": [
                self._value_range_response(range_name, params)
                for range_name in ranges
            ]
        }

    def values_update(self, spreadsheet_id, range_name, params=None, body=None):
        self.values_update_calls.append(
            {
                "spreadsheet_id": spreadsheet_id,
                "range_name": range_name,
                "params": params,
                "body": body,
            }
        )
        return {"ok": True}

    def values_batch_update(self, spreadsheet_id, body=None):
        self.values_batch_update_calls.append(
            {"spreadsheet_id": spreadsheet_id, "body": body}
        )
        return {"ok": True}

    def fetch_sheet_metadata(self, spreadsheet_id):
        return deepcopy(self.metadata)


def make_worksheet(client=None):
    client = client or RecordingClient()
    worksheet = Worksheet(
        SPREADSHEET_ID,
        client,
        {
            "sheetId": 123,
            "title": "Sheet1",
            "index": 0,
            "gridProperties": {"rowCount": 100, "columnCount": 26},
        },
    )
    return worksheet, client


def test_accepted_kwargs_and_filter_dict_values_are_removed():
    assert not hasattr(utils, "accepted_kwargs")
    assert not hasattr(utils, "filter_dict_values")


@pytest.mark.parametrize(
    ("method_name", "optional_parameters"),
    [
        (
            "get_values",
            {
                "range_name": None,
                "combine_merged_cells": False,
                "major_dimension": None,
                "value_render_option": None,
                "date_time_render_option": None,
            },
        ),
        (
            "get_all_values",
            {
                "major_dimension": None,
                "value_render_option": None,
                "date_time_render_option": None,
            },
        ),
        (
            "row_values",
            {
                "major_dimension": None,
                "value_render_option": None,
                "date_time_render_option": None,
            },
        ),
        (
            "get",
            {
                "range_name": None,
                "major_dimension": None,
                "value_render_option": None,
                "date_time_render_option": None,
            },
        ),
        (
            "batch_get",
            {
                "major_dimension": None,
                "value_render_option": None,
                "date_time_render_option": None,
            },
        ),
        (
            "update",
            {
                "values": None,
                "raw": True,
                "major_dimension": None,
                "value_input_option": None,
                "include_values_in_response": None,
                "response_value_render_option": None,
                "response_date_time_render_option": None,
            },
        ),
        (
            "batch_update",
            {
                "raw": True,
                "value_input_option": None,
                "include_values_in_response": None,
                "response_value_render_option": None,
                "response_date_time_render_option": None,
            },
        ),
    ],
)
def test_former_decorator_kwargs_are_explicit_arguments(
    method_name, optional_parameters
):
    signature = inspect.signature(getattr(Worksheet, method_name))

    assert not any(
        parameter.kind is inspect.Parameter.VAR_KEYWORD
        for parameter in signature.parameters.values()
    )

    for name, default in optional_parameters.items():
        assert name in signature.parameters
        assert signature.parameters[name].default == default


def test_read_methods_work_with_defaults_and_omit_unset_options():
    worksheet, client = make_worksheet()

    assert worksheet.get("A1").first() == "a"
    assert client.values_get_calls[-1]["params"] == {}

    assert worksheet.get_values("A1:B2") == [["a", "b"], ["c", ""]]
    assert client.values_get_calls[-1]["params"] == {}

    assert worksheet.get_all_values() == [["a", "b"], ["c", ""]]
    assert client.values_get_calls[-1]["params"] == {}

    assert worksheet.row_values(2) == ["a", "b"]
    assert client.values_get_calls[-1]["params"] == {}

    batch = worksheet.batch_get(["A1"])
    assert isinstance(batch[0], ValueRange)
    assert batch[0].first() == "a"
    assert client.values_batch_get_calls[-1]["params"] == {}


def test_every_read_method_forwards_the_explicit_options():
    worksheet, client = make_worksheet()
    options = {
        "major_dimension": Dimension.cols,
        "value_render_option": ValueRenderOption.unformatted,
        "date_time_render_option": DateTimeOption.formatted_string,
    }
    expected_params = read_params(**options)

    worksheet.get("A1", **options)
    worksheet.get_values("A1:B2", **options)
    worksheet.get_all_values(**options)
    worksheet.row_values(3, **options)
    worksheet.batch_get(["A1", "", "B2:C3"], **options)

    assert [call["range_name"] for call in client.values_get_calls] == [
        "'Sheet1'!A1",
        "'Sheet1'!A1:B2",
        "'Sheet1'",
        "'Sheet1'!A3:3",
    ]
    assert all(
        call["params"] == expected_params for call in client.values_get_calls
    )

    batch_call = client.values_batch_get_calls[0]
    assert batch_call["spreadsheet_id"] == SPREADSHEET_ID
    assert batch_call["ranges"] == ["'Sheet1'!A1", "'Sheet1'!B2:C3"]
    assert batch_call["params"] == expected_params


def test_read_methods_accept_explicit_none_and_forward_only_set_options():
    worksheet, client = make_worksheet()

    worksheet.get(
        "A1",
        major_dimension=None,
        value_render_option=ValueRenderOption.formula,
        date_time_render_option=None,
    )
    assert client.values_get_calls[-1]["params"] == {
        "valueRenderOption": ValueRenderOption.formula
    }

    worksheet.batch_get(
        ["A1"],
        major_dimension=Dimension.cols,
        value_render_option=None,
        date_time_render_option=None,
    )
    assert client.values_batch_get_calls[-1]["params"] == {
        "majorDimension": Dimension.cols
    }


def test_write_methods_work_with_defaults_and_omit_unset_options():
    worksheet, client = make_worksheet()

    worksheet.update("A1", 42)
    update_call = client.values_update_calls[0]
    assert update_call["range_name"] == "'Sheet1'!A1"
    assert update_call["params"] == {
        "valueInputOption": ValueInputOption.raw,
    }
    assert update_call["body"] == {"values": [[42]]}

    data = [{"range": "A1", "values": [[42]]}]
    original_data = deepcopy(data)
    worksheet.batch_update(data)

    batch_call = client.values_batch_update_calls[0]
    assert batch_call["body"] == {
        "valueInputOption": ValueInputOption.raw,
        "data": [{"range": "'Sheet1'!A1", "values": [[42]]}],
    }
    assert data == original_data


def test_write_methods_forward_options_and_preserve_false_values():
    worksheet, client = make_worksheet()

    values = [[1, 2], [3, 4]]
    worksheet.update(
        "A1:B2",
        values,
        raw=False,
        major_dimension=Dimension.rows,
        include_values_in_response=False,
        response_value_render_option=ValueRenderOption.unformatted,
        response_date_time_render_option=DateTimeOption.formatted_string,
    )

    update_call = client.values_update_calls[0]
    assert update_call["params"] == {
        "valueInputOption": ValueInputOption.user_entered,
        "includeValuesInResponse": False,
        "responseValueRenderOption": ValueRenderOption.unformatted,
        "responseDateTimeRenderOption": DateTimeOption.formatted_string,
    }
    assert update_call["body"] == {
        "values": values,
        "majorDimension": Dimension.rows,
    }

    data = [
        {"range": "A1:B1", "values": [[1, 2]]},
        {"range": "C3", "values": [[3]]},
    ]
    worksheet.batch_update(
        data,
        raw=True,
        value_input_option=ValueInputOption.user_entered,
        include_values_in_response=False,
        response_value_render_option=ValueRenderOption.formatted,
        response_date_time_render_option=DateTimeOption.serial_number,
    )

    assert client.values_batch_update_calls[0]["body"] == {
        "valueInputOption": ValueInputOption.user_entered,
        "includeValuesInResponse": False,
        "responseValueRenderOption": ValueRenderOption.formatted,
        "responseDateTimeRenderOption": DateTimeOption.serial_number,
        "data": [
            {"range": "'Sheet1'!A1:B1", "values": [[1, 2]]},
            {"range": "'Sheet1'!C3", "values": [[3]]},
        ],
    }


def test_get_values_still_combines_merged_cells_when_requested():
    worksheet, client = make_worksheet()
    client.values = [["1", ""], ["", ""]]
    client.metadata = {
        "sheets": [
            {
                "properties": {"title": "Sheet1"},
                "merges": [
                    {
                        "startRowIndex": 0,
                        "endRowIndex": 2,
                        "startColumnIndex": 0,
