import inspect
from copy import deepcopy

import pytest

import gspread.utils as utils
from gspread.utils import (
    DateTimeOption,
    Dimension,
    ValueInputOption,
    ValueRenderOption,
)
from gspread.worksheet import ValueRange, Worksheet


READ_PARAMS = {
    "majorDimension",
    "valueRenderOption",
    "dateTimeRenderOption",
}
UPDATE_PARAMS = {
    "valueInputOption",
    "includeValuesInResponse",
    "responseValueRenderOption",
    "responseDateTimeRenderOption",
}


class RecordingClient:
    """Offline client double that records the requests made by Worksheet."""

    def __init__(self):
        self.calls = []
        self.values_get_response = {
            "range": "'Sheet1'!A1",
            "majorDimension": "ROWS",
            "values": [["value"]],
        }
        self.sheet_metadata = {"sheets": []}

    def values_get(self, spreadsheet_id, range_name, params=None):
        self.calls.append(
            {
                "method": "values_get",
                "spreadsheet_id": spreadsheet_id,
                "range_name": range_name,
                "params": deepcopy(params),
            }
        )
        return deepcopy(self.values_get_response)

    def values_batch_get(self, spreadsheet_id, ranges=None, params=None):
        self.calls.append(
            {
                "method": "values_batch_get",
                "spreadsheet_id": spreadsheet_id,
                "ranges": deepcopy(ranges),
                "params": deepcopy(params),
            }
        )
        major_dimension = (params or {}).get("majorDimension") or "ROWS"
        return {
            "valueRanges": [
                {
                    "range": range_name,
                    "majorDimension": major_dimension,
                    "values": [[range_name]],
                }
                for range_name in ranges
            ]
        }

    def values_update(self, spreadsheet_id, range_name, params=None, body=None):
        self.calls.append(
            {
                "method": "values_update",
                "spreadsheet_id": spreadsheet_id,
                "range_name": range_name,
                "params": deepcopy(params),
                "body": deepcopy(body),
            }
        )
        return {
            "spreadsheetId": spreadsheet_id,
            "updatedRange": range_name,
        }

    def values_batch_update(self, spreadsheet_id, body=None):
        self.calls.append(
            {
                "method": "values_batch_update",
                "spreadsheet_id": spreadsheet_id,
                "body": deepcopy(body),
            }
        )
        return {"spreadsheetId": spreadsheet_id}

    def fetch_sheet_metadata(self, spreadsheet_id):
        self.calls.append(
            {
                "method": "fetch_sheet_metadata",
                "spreadsheet_id": spreadsheet_id,
            }
        )
        return deepcopy(self.sheet_metadata)


def make_worksheet():
    client = RecordingClient()
    worksheet = Worksheet(
        "spreadsheet-id",
        client,
        {
            "sheetId": 0,
            "title": "Sheet1",
            "index": 0,
            "gridProperties": {"rowCount": 100, "columnCount": 26},
        },
    )
    return worksheet, client


def calls_for(client, method):
    return [call for call in client.calls if call["method"] == method]


def assert_only_none_options(mapping, allowed_keys):
    """A fix may omit None options or pass them through as None."""
    assert set(mapping).issubset(allowed_keys)
    assert all(value is None for value in mapping.values())


def test_obsolete_helpers_are_removed():
    assert not hasattr(utils, "accepted_kwargs")
    assert not hasattr(utils, "filter_dict_values")


def test_former_decorated_methods_have_explicit_typed_call_shapes():
    expected_defaults = {
        "get_values": {
            "range_name": None,
            "combine_merged_cells": False,
            "major_dimension": None,
            "value_render_option": None,
            "date_time_render_option": None,
        },
        "get_all_values": {
            "major_dimension": None,
            "value_render_option": None,
            "date_time_render_option": None,
        },
        "row_values": {
            "major_dimension": None,
            "value_render_option": None,
            "date_time_render_option": None,
        },
        "get": {
            "range_name": None,
            "major_dimension": None,
            "value_render_option": None,
            "date_time_render_option": None,
        },
        "batch_get": {
            "major_dimension": None,
            "value_render_option": None,
            "date_time_render_option": None,
        },
        "update": {
            "values": None,
            "raw": True,
            "major_dimension": None,
            "value_input_option": None,
            "include_values_in_response": None,
            "response_value_render_option": None,
            "response_date_time_render_option": None,
        },
        "batch_update": {
            "raw": True,
            "value_input_option": None,
            "include_values_in_response": None,
            "response_value_render_option": None,
            "response_date_time_render_option": None,
        },
    }
    required_arguments = {
        "row_values": ("row",),
        "batch_get": ("ranges",),
        "update": ("range_name",),
        "batch_update": ("data",),
    }

    for method_name, defaults in expected_defaults.items():
        parameters = inspect.signature(getattr(Worksheet, method_name)).parameters

        assert not any(
            parameter.kind is inspect.Parameter.VAR_KEYWORD
            for parameter in parameters.values()
        ), method_name

        for name, default in defaults.items():
            assert name in parameters, (method_name, name)
            assert parameters[name].default == default, (method_name, name)

        for name in required_arguments.get(method_name, ()):
            assert name in parameters
            assert parameters[name].default is inspect.Parameter.empty


def test_get_passes_enum_options_and_handles_unset_options():
    worksheet, client = make_worksheet()

    result = worksheet.get()
    assert isinstance(result, ValueRange)
    default_call = calls_for(client, "values_get")[0]
    assert default_call["range_name"] == "'Sheet1'"
    assert_only_none_options(default_call["params"], READ_PARAMS)

    result = worksheet.get(
        "A1:B2",
        major_dimension=Dimension.cols,
        value_render_option=ValueRenderOption.unformatted,
        date_time_render_option=DateTimeOption.formatted_string,
    )

    assert isinstance(result, ValueRange)
    option_call = calls_for(client, "values_get")[1]
    assert option_call["range_name"] == "'Sheet1'!A1:B2"
    assert option_call["params"] == {
        "majorDimension": Dimension.cols,
        "valueRenderOption": ValueRenderOption.unformatted,
        "dateTimeRenderOption": DateTimeOption.formatted_string,
    }


def test_value_reading_convenience_methods_forward_all_options():
    worksheet, client = make_worksheet()

    client.values_get_response = {
        "range": "'Sheet1'!A1:B2",
        "majorDimension": "ROWS",
        "values": [["a"], ["b", "c"]],
    }
    values = worksheet.get_values(
        "A1:B2",
        False,
        major_dimension=Dimension.rows,
        value_render_option=ValueRenderOption.formula,
        date_time_render_option=DateTimeOption.serial_number,
    )
    assert values == [["a", ""], ["b", "c"]]

    client.values_get_response = {
        "range": "'Sheet1'",
        "majorDimension": "COLUMNS",
        "values": [["all"]],
    }
    all_values = worksheet.get_all_values(
        major_dimension=Dimension.cols,
        value_render_option=ValueRenderOption.unformatted,
        date_time_render_option=DateTimeOption.formatted_string,
    )
    assert all_values == [["all"]]

    client.values_get_response = {
        "range": "'Sheet1'!A3:3",
        "majorDimension": "ROWS",
        "values": [["r1", "r2"]],
    }
    row_values = worksheet.row_values(
        3,
        major_dimension=Dimension.rows,
        value_render_option=ValueRenderOption.formatted,
        date_time_render_option=DateTimeOption.serial_number,
    )
    assert row_values == ["r1", "r2"]

    calls = calls_for(client, "values_get")
    assert calls[0]["range_name"] == "'Sheet1'!A1:B2"
    assert calls[0]["params"] == {
        "majorDimension": Dimension.rows,
        "valueRenderOption": ValueRenderOption.formula,
        "dateTimeRenderOption": DateTimeOption.serial_number,
    }
    assert calls[1]["range_name"] == "'Sheet1'"
