def test_batch_update_defaults_options_and_absolutizes_ranges():
    worksheet, client = make_worksheet()
    data = [
        {"range": "A1", "values": [[1]]},
        {"range": "B2:C3", "values": [[2, 3]]},
    ]
    expected_data = [
        {"range": "'Sheet1'!A1", "values": [[1]]},
        {"range": "'Sheet1'!B2:C3", "values": [[2, 3]]},
    ]

    worksheet.batch_update(data)
    default_call = calls_for(client, "values_batch_update")[0]
    default_body = default_call["body"]
    assert default_body["valueInputOption"] == ValueInputOption.raw
    assert default_body["data"] == expected_data
    assert set(default_body).issubset(UPDATE_PARAMS | {"data"})
    for name in UPDATE_PARAMS - {"valueInputOption"}:
        assert default_body.get(name) is None

    worksheet.batch_update(
        data,
        raw=False,
        include_values_in_response=False,
        response_value_render_option=ValueRenderOption.formula,
        response_date_time_render_option=DateTimeOption.serial_number,
    )
    option_call = calls_for(client, "values_batch_update")[1]
    assert option_call["body"] == {
        "valueInputOption": ValueInputOption.user_entered,
        "includeValuesInResponse": False,
        "responseValueRenderOption": ValueRenderOption.formula,
        "responseDateTimeRenderOption": DateTimeOption.serial_number,
        "data": expected_data,
    }

    worksheet.batch_update(
        data,
        raw=False,
        value_input_option=ValueInputOption.raw,
    )
    override_call = calls_for(client, "values_batch_update")[2]
    assert override_call["body"]["valueInputOption"] == ValueInputOption.raw

    # Building the request must not rewrite the caller's dictionaries.
    assert data[0]["range"] == "A1"
    assert data[1]["range"] == "B2:C3"


