import inspect
from copy import deepcopy

import pytest

import gspread.utils as utils
from gspread.utils import (
    DateTimeOption,
    Dimension,
    ValueInputOption,
    ValueRenderOption,
)
from gspread.worksheet import ValueRange, Worksheet


class RecordingClient:
    """Offline client double recording the requests made by Worksheet."""

    def __init__(self):
        self.values = [["a"], ["b", "c"]]
        self.values_get_calls = []
        self.values_batch_get_calls = []
        self.values_update_calls = []
        self.values_batch_update_calls = []
        self.metadata_calls = []

    def values_get(self, spreadsheet_id, range_name, params=None):
        params = {} if params is None else params
        self.values_get_calls.append(
            {
                "spreadsheet_id": spreadsheet_id,
                "range_name": range_name,
                "params": params,
            }
        )
        return {
            "range": range_name,
            "majorDimension": params.get("majorDimension") or Dimension.rows,
            "values": deepcopy(self.values),
        }

    def values_batch_get(self, spreadsheet_id, ranges=None, params=None):
        params = {} if params is None else params
        ranges = [] if ranges is None else ranges
        self.values_batch_get_calls.append(
            {
                "spreadsheet_id": spreadsheet_id,
                "ranges": ranges,
                "params": params,
            }
        )
        return {
            "valueRanges": [
                {
                    "range": range_name,
                    "majorDimension": params.get("majorDimension")
                    or Dimension.rows,
                    "values": deepcopy(self.values),
                }
                for range_name in ranges
            ]
        }

    def values_update(self, spreadsheet_id, range_name, params=None, body=None):
        self.values_update_calls.append(
            {
                "spreadsheet_id": spreadsheet_id,
                "range_name": range_name,
                "params": params,
                "body": body,
            }
        )
        return {
            "spreadsheetId": spreadsheet_id,
            "updatedRange": range_name,
        }

    def values_batch_update(self, spreadsheet_id, body=None):
        self.values_batch_update_calls.append(
            {"spreadsheet_id": spreadsheet_id, "body": body}
        )
        return {"spreadsheetId": spreadsheet_id, "responses": []}

    def fetch_sheet_metadata(self, spreadsheet_id):
        self.metadata_calls.append(spreadsheet_id)
        return {
            "sheets": [
                {
                    "properties": {"sheetId": 123, "title": "Sheet 1"},
                    "merges": [
                        {
                            "startRowIndex": 0,
                            "endRowIndex": 2,
                            "startColumnIndex": 0,
                            "endColumnIndex": 2,
                        }
                    ],
                }
            ]
        }


