"""Regression tests for removing accepted_kwargs and filter_dict_values.

These tests use a recording client instead of making any network requests.  They
check both the new explicit public signatures and the request behavior that
existed before the decorator was removed.
"""

import inspect
from copy import deepcopy

import pytest

import gspread.utils as utils
from gspread.worksheet import Worksheet


def compact(mapping):
    """Ignore optional None values, as the HTTP transport does."""
    return {
        key: value
        for key, value in (mapping or {}).items()
        if value is not None
    }


class RecordingClient:
    def __init__(self):
        self.values_get_calls = []
        self.values_batch_get_calls = []
        self.values_update_calls = []
        self.values_batch_update_calls = []
        self.fetch_sheet_metadata_calls = []

        self.values_get_response = {
            "range": "'Sheet 1'!A1:B2",
            "majorDimension": "ROWS",
            "values": [["a", "b"], ["c"]],
        }
        self.values_batch_get_response = {
            "valueRanges": [
                {
                    "range": "'Sheet 1'!A1:A2",
                    "majorDimension": "ROWS",
                    "values": [["a"], ["b"]],
                },
                {
                    "range": "'Sheet 1'!C3",
                    "majorDimension": "ROWS",
                    "values": [["c"]],
                },
            ]
        }
        self.sheet_metadata = {"sheets": []}

    def values_get(self, spreadsheet_id, range_name, params=None):
        self.values_get_calls.append(
            {
                "spreadsheet_id": spreadsheet_id,
                "range_name": range_name,
                "params": params,
            }
        )
        return deepcopy(self.values_get_response)

    def values_batch_get(self, spreadsheet_id, ranges, params=None):
        self.values_batch_get_calls.append(
            {
                "spreadsheet_id": spreadsheet_id,
                "ranges": ranges,
                "params": params,
            }
        )
        return deepcopy(self.values_batch_get_response)

    def values_update(self, spreadsheet_id, range_name, params=None, body=None):
        self.values_update_calls.append(
            {
                "spreadsheet_id": spreadsheet_id,
                "range_name": range_name,
                "params": params,
                "body": body,
            }
        )
        return {
            "spreadsheetId": spreadsheet_id,
            "updatedRange": range_name,
        }

    def values_batch_update(self, spreadsheet_id, body=None):
        self.values_batch_update_calls.append(
            {"spreadsheet_id": spreadsheet_id, "body": body}
        )
        return {"spreadsheetId": spreadsheet_id, "responses": []}

    def fetch_sheet_metadata(self, spreadsheet_id):
        self.fetch_sheet_metadata_calls.append(spreadsheet_id)
        return deepcopy(self.sheet_metadata)


def make_worksheet():
    client = RecordingClient()
    worksheet = Worksheet(
        "spreadsheet-id",
        client,
        {
            "sheetId": 123,
            "title": "Sheet 1",
            "index": 0,
            "gridProperties": {"rowCount": 100, "columnCount": 26},
        },
    )
    return worksheet, client


def test_decorator_and_filter_helper_are_removed():
    assert not hasattr(utils, "accepted_kwargs")
    assert not hasattr(utils, "filter_dict_values")


@pytest.mark.parametrize(
    "method_name, expected_defaults",
    [
        (
            "get_values",
            {
                "range_name": None,
                "combine_merged_cells": False,
                "major_dimension": None,
                "value_render_option": None,
                "date_time_render_option": None,
            },
        ),
        (
            "get_all_values",
            {
                "major_dimension": None,
                "value_render_option": None,
                "date_time_render_option": None,
            },
        ),
        (
            "row_values",
            {
                "major_dimension": None,
                "value_render_option": None,
                "date_time_render_option": None,
            },
        ),
        (
            "get",
            {
                "range_name": None,
                "major_dimension": None,
                "value_render_option": None,
                "date_time_render_option": None,
            },
        ),
        (
            "batch_get",
            {
                "major_dimension": None,
                "value_render_option": None,
                "date_time_render_option": None,
            },
        ),
        (
            "update",
            {
                "values": None,
                "raw": True,
