                "include_values_in_response": None,
                "response_value_render_option": None,
                "response_date_time_render_option": None,
            },
        ),
        (
            "batch_update",
            {
                "raw": True,
                "value_input_option": None,
                "include_values_in_response": None,
                "response_value_render_option": None,
                "response_date_time_render_option": None,
            },
        ),
    ],
)
def test_former_decorator_options_are_explicit_arguments(
    method_name, expected_defaults
):
    parameters = inspect.signature(getattr(Worksheet, method_name)).parameters

    assert not any(
        parameter.kind is inspect.Parameter.VAR_KEYWORD
        for parameter in parameters.values()
    )

    for name, default in expected_defaults.items():
        assert name in parameters
        assert parameters[name].kind in (
            inspect.Parameter.POSITIONAL_OR_KEYWORD,
            inspect.Parameter.KEYWORD_ONLY,
        )
        assert parameters[name].default == default


