    call = client.values_update_calls[-1]
    assert call["range_name"] == "'Sheet 1'!A1"
    assert compact(call["params"]) == {"valueInputOption": "RAW"}
    assert compact(call["body"]) == {"values": [[42]]}

    worksheet.update("A2", [["x"]], raw=False)

    call = client.values_update_calls[-1]
    assert compact(call["params"]) == {"valueInputOption": "USER_ENTERED"}
