import unittest

from streamlink.compat import is_win32
from streamlink_cli.output import PlayerOutput
from tests.mock import patch
from tests.test_cmdline import CommandLineTestCase


@unittest.skipIf(is_win32, "test only applicable on a POSIX OS")
class TestMpvTitleCommandLinePOSIX(CommandLineTestCase):
    def test_title_value_is_attached_to_mpv_option(self):
        # Arguments passed through Popen must not contain literal shell quotes.
        self._test_args(
            ["streamlink", "-p", "/usr/bin/mpv", "--title", "{title}",
             "http://test.se", "test"],
            ["/usr/bin/mpv", "--title=Test Title", "-"]
        )

    def test_default_title_is_attached_to_mpv_option(self):
        self._test_args(
            ["streamlink", "-p", "/usr/bin/mpv", "http://test.se", "test"],
            ["/usr/bin/mpv", "--title=http://test.se", "-"]
        )

    def test_unicode_title_is_a_single_mpv_argument(self):
        self._test_args(
            ["streamlink", "-p", "/usr/bin/mpv", "--title", "{author}",
             "http://test.se", "test"],
            ["/usr/bin/mpv", u"--title=Tѥst Āuƭhǿr", "-"]
        )

    def test_mpv_title_is_added_after_existing_player_arguments(self):
        self._test_args(
            ["streamlink", "-p", "/usr/bin/mpv --cache 2048",
             "--title", "{title}", "http://test.se", "test"],
            ["/usr/bin/mpv", "--cache", "2048", "--title=Test Title", "-"]
        )


class TestMpvTitleArguments(unittest.TestCase):
    @patch("streamlink_cli.output.is_win32", new=False)
    def test_posix_argument_does_not_contain_literal_shell_quotes(self):
        output = PlayerOutput(
            "/usr/bin/mpv", title="Test Title", quiet=False
        )

        self.assertEqual(
            output._create_arguments(),
            ["/usr/bin/mpv", "--title=Test Title", "-"]
        )

    @patch("streamlink_cli.output.is_win32", new=False)
    def test_posix_property_expansion_is_escaped_without_shell_quoting(self):
        output = PlayerOutput(
            "/usr/bin/mpv", title="Test $Title", quiet=False
        )

        self.assertEqual(
            output._create_arguments(),
            ["/usr/bin/mpv", "--title=Test $$Title", "-"]
        )

    @patch("streamlink_cli.output.is_win32", new=False)
    def test_empty_title_still_uses_equals_syntax(self):
        output = PlayerOutput("/usr/bin/mpv", title="", quiet=False)

        self.assertEqual(
            output._create_arguments(),
            ["/usr/bin/mpv", "--title=", "-"]
        )

    @patch("streamlink_cli.output.is_win32", new=False)
    def test_no_title_does_not_add_an_mpv_option(self):
        output = PlayerOutput("/usr/bin/mpv", title=None, quiet=False)

        self.assertEqual(
            output._create_arguments(),
            ["/usr/bin/mpv", "-"]
        )

    @patch("streamlink_cli.output.is_win32", new=True)
    def test_windows_command_line_keeps_title_and_value_in_one_argument(self):
        output = PlayerOutput("mpv", title="Test Title", quiet=False)

        # list2cmdline supplies any required double quotes; POSIX single
        # quotes must not become part of the title passed to mpv.
        self.assertEqual(
            output._create_arguments(),
            'mpv "--title=Test Title" -'
        )

