                "--title", "A=B $C",
                "http://test.se", "test",
            ],
            ["/usr/bin/mpv", "--title=A=B $$C", "-"],
        )

    def test_non_mpv_title_syntax_is_unchanged(self):
        self._test_args(
            [
                "streamlink",
                "-p", "/usr/bin/vlc",
                "--title", "{title}",
                "http://test.se", "test",
            ],
            [
                "/usr/bin/vlc",
                "--input-title-format", "Test Title",
                "-",
            ],
        )

