def _player_arguments(monkeypatch, cmd, title, **kwargs):
    # Force the POSIX list-based argument construction on every test platform.
    monkeypatch.setattr("streamlink_cli.output.is_win32", False)
    player = PlayerOutput(cmd, quiet=False, title=title, **kwargs)
    return player._create_arguments()


@pytest.mark.parametrize("title", [
    u"Test Title",
    u"https://www.twitch.tv/videos/533706108",
    u"Tѥst Āuƭhǿr",
    u"",
    u"--not-an-option",
    u'title with "quotes" and = signs',
])
