import unittest

import pytest

from streamlink.compat import is_win32
from streamlink_cli.output import PlayerOutput
import streamlink_cli.output as output_module
from tests.test_cmdline import CommandLineTestCase


def _create_player_args(cmd, title, args="{filename}", **kwargs):
    # quiet=False avoids opening devnull handles; no player process is started.
    player = PlayerOutput(cmd, args=args, title=title, quiet=False, **kwargs)
    return player._create_arguments()


@pytest.mark.skipif(is_win32, reason="POSIX argument lists are tested separately from Windows command lines")
class TestPlayerTitleArguments:
    def test_mpv_title_from_issue_uses_equals_syntax(self):
        url = "https://www.twitch.tv/videos/533706108"

        assert _create_player_args("/home/zouhair/mpv.exe", url) == [
            "/home/zouhair/mpv.exe",
            "--title=" + url,
            "-",
        ]

    @pytest.mark.parametrize(
        "title, expected",
        [
            ("Test Title", "--title=Test Title"),
            ("", "--title="),
            (u"Tѥst Āuƭhǿr = mpv", u"--title=Tѥst Āuƭhǿr = mpv"),
            ("--looks-like-an-option", "--title=---looks-like-an-option".replace("=---", "=--")),
            ('A "quoted" title', '--title=A "quoted" title'),
        ],
    )
    def test_mpv_title_and_value_are_one_argument(self, title, expected):
        args = _create_player_args("/usr/bin/mpv", title)

        assert args == ["/usr/bin/mpv", expected, "-"]
        assert "--title" not in args
        assert sum(arg.startswith("--title=") for arg in args) == 1

    @pytest.mark.parametrize(
        "title, escaped_title",
        [
            ("no escape $$ codes $", "no escape $$$$ codes $$"),
            (r"\$> begins with escape code $$", "$> begins with escape code $$"),
        ],
    )
    def test_mpv_property_expansion_escaping_is_preserved(self, title, escaped_title):
        assert _create_player_args("/usr/bin/mpv", title) == [
            "/usr/bin/mpv",
            "--title=" + escaped_title,
            "-",
        ]

    def test_mpv_title_is_added_after_existing_player_arguments(self):
        assert _create_player_args('"/opt/mpv builds/mpv" --idle', "Test Title") == [
            "/opt/mpv builds/mpv",
            "--idle",
            "--title=Test Title",
            "-",
        ]

    def test_mpv_without_a_title_does_not_add_a_title_option(self):
        assert _create_player_args("/usr/bin/mpv", None) == [
            "/usr/bin/mpv",
            "-",
        ]

    def test_vlc_title_syntax_is_unchanged(self):
        # mpv's new double-dash requirement must not be applied to other players.
        assert _create_player_args("/usr/bin/vlc", "Test Title") == [
            "/usr/bin/vlc",
            "--input-title-format",
            "Test Title",
            "-",
        ]


def test_windows_mpv_title_remains_one_quoted_command_line_argument(monkeypatch):
    monkeypatch.setattr(output_module, "is_win32", True)

    command = _create_player_args("mpv.exe", "Test Title")
    if isinstance(command, bytes):
        command = command.decode("utf-8")

    # list2cmdline quotes the complete --title=value argument, including spaces.
    assert command == 'mpv.exe "--title=Test Title" -'


@unittest.skipIf(is_win32, "test only applicable on a POSIX OS")
class TestMpvTitleCommandLine(CommandLineTestCase):
    def test_explicit_mpv_title_uses_equals_syntax(self):
        self._test_args(
            [
                "streamlink",
                "-p",
                "/usr/bin/mpv",
                "--title",
                "{title}",
                "http://test.se",
                "test",
            ],
            ["/usr/bin/mpv", "--title=Test Title", "-"],
        )

    def test_default_mpv_title_uses_equals_syntax(self):
        self._test_args(
            ["streamlink", "-p", "/usr/bin/mpv", "http://test.se", "test"],
            ["/usr/bin/mpv", "--title=http://test.se", "-"],
        )

