import unittest

from streamlink.compat import is_win32
from streamlink.utils import get_filesystem_encoding
from streamlink_cli.output import PlayerOutput
from tests.mock import patch
from tests.test_cmdline import CommandLineTestCase


@unittest.skipIf(is_win32, "test only applicable on a POSIX OS")
class TestMpvTitleCommandLinePOSIX(CommandLineTestCase):
    def test_explicit_title_is_passed_using_mpv_equals_syntax(self):
        """The title and its value must be one --title=value argument."""
        self._test_args(
            [
                "streamlink",
                "-p", "/usr/bin/mpv",
                "--title", "{title}",
                "http://test.se", "test",
            ],
            ["/usr/bin/mpv", "--title=Test Title", "-"],
        )

    def test_default_title_uses_equals_syntax_with_player_arguments(self):
        """Mirror the reported invocation, including existing mpv arguments."""
        self._test_args(
            [
                "streamlink",
                "-p", "/usr/bin/mpv --cache 2048",
                "http://test.se", "test",
            ],
            [
                "/usr/bin/mpv",
                "--cache", "2048",
                "--title=http://test.se",
                "-",
            ],
        )

    def test_unicode_title_remains_in_the_same_argument(self):
        self._test_args(
            [
                "streamlink",
                "-p", "/usr/bin/mpv",
                "--title", "{author}",
                "http://test.se", "test",
            ],
            ["/usr/bin/mpv", u"--title=Tѥst Āuƭhǿr", "-"],
        )


@unittest.skipIf(is_win32, "test only applicable on a POSIX OS")
class TestMpvTitleArgumentsPOSIX(unittest.TestCase):
    def create_arguments(self, title, player="/usr/bin/mpv"):
        output = PlayerOutput(player, title=title, quiet=False)
        return output._create_arguments()

    def test_empty_title_still_uses_an_equals_argument(self):
        self.assertEqual(
            self.create_arguments(""),
            ["/usr/bin/mpv", "--title=", "-"],
        )

    def test_mpv_property_expansion_escaping_is_preserved(self):
        self.assertEqual(
            self.create_arguments("Price $5"),
            ["/usr/bin/mpv", "--title=Price $$5", "-"],
        )

    def test_vlc_title_argument_format_is_unchanged(self):
        self.assertEqual(
            self.create_arguments("Test Title", player="/usr/bin/vlc"),
            [
                "/usr/bin/vlc",
                "--input-title-format", "Test Title",
                "-",
            ],
        )


class TestMpvTitleWindowsCommandLine(unittest.TestCase):
    def test_windows_command_line_quotes_the_complete_title_argument(self):
        # Construct while the host platform rules are active, then exercise
        # the Windows command-line serialization independently of the host OS.
        output = PlayerOutput("mpv", title="Test Title", quiet=False)
        with patch("streamlink_cli.output.is_win32", True):
            command = output._create_arguments()

        if isinstance(command, bytes):
            command = command.decode(get_filesystem_encoding())

        # It must not be serialized as: mpv --title "Test Title" -
        self.assertEqual(command, 'mpv "--title=Test Title" -')
